import pandas as pd
from datetime import datetime

orders = pd.read_excel("DuLieuBanHang.xlsx", sheet_name="DanhSachHoaDon")
payments = pd.read_excel("DuLieuBanHang.xlsx", sheet_name="SoQuy")

# Parse order date (Thời gian): mixed int serial and string
def parse_order_date(v):
    if isinstance(v, (int, float)):
        # Excel serial date
        return pd.to_datetime(v, unit='d', origin=pd.Timestamp(1899,12,30))
    return pd.to_datetime(v, errors='coerce')

orders['date'] = orders['Thời gian'].apply(parse_order_date)
print("Order date sample:", orders['date'].head(5).tolist())
print("Order date null:", orders['date'].isna().sum())

# Parse payment date
def parse_pay_date(v):
    if isinstance(v, (int, float)):
        return pd.to_datetime(v, unit='d', origin=pd.Timestamp(1899,12,30))
    return pd.to_datetime(v, errors='coerce')

payments['pay_date'] = payments['Thời gian'].apply(parse_pay_date)
print("\nPay date sample:", payments['pay_date'].head(5).tolist())
print("Pay date null:", payments['pay_date'].isna().sum())
print("Pay shape:", payments.shape)

# Normalize status
def norm_status(s):
    s = str(s).strip().lower()
    if 'hủy' in s:
        return 'cancelled'
    if 'trả hàng' in s or 'trả hàng' in s:
        return 'returned'
    return 'other'  # hoàn thành, đã lấy, đang xử lý

orders['status_norm'] = orders['Trạng thái'].apply(norm_status)
print("\nStatus norm:", orders['status_norm'].value_counts().to_dict())

# Normalize payment method
def norm_paymethod(s):
    s = str(s).strip().lower()
    if 'cod' in s or 'thu hộ' in s:
        return 'cod'
    return 'other'

orders['paymethod_norm'] = orders['Phương thức thanh toán'].apply(norm_paymethod)
print("Paymethod norm:", orders['paymethod_norm'].value_counts().to_dict())

